-- 세트 496: k8s Deployment 배포 옵션 손연습: Recreate, rollout pause·resume, minReadySeconds, revisionHistoryLimit, create deployment -- 명령, generateName, shareProcessNamespace, change-cause, 현재 ReplicaSet
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_k8s_deploy_options_lab_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (496, 1, '내리고 올리는 배포로 바꾸기 (strategy: Recreate)', '**배경** — Deployment 의 기본 전략 `RollingUpdate` 는 새 Pod 를 하나씩 띄우며 옛 Pod 를 내려 **무중단**으로 바꿉니다. **`Recreate`** 는 옛 Pod 를 **전부 내린 뒤** 새 Pod 를 올려 잠깐 중단되지만, 두 버전이 동시에 떠서는 안 되는 앱(DB 스키마 변경, 단일 쓰기 잠금 등)에 씁니다. 전략을 `Recreate` 로 바꿀 때는 **`rollingUpdate` 설정을 비워야** 합니다. Deployment `web` 이 있습니다.

**문제** — `web` 의 전략을 **`Recreate`** 로 바꾸세요.', '`kubectl patch deploy web -p ''{"spec":{"strategy":{"type":"Recreate","rollingUpdate":null}}}''`', 'kubectl patch deploy web -n $NS -p ''{"spec":{"strategy":{"type":"Recreate","rollingUpdate":null}}}''
kubectl get deploy web -n $NS -o jsonpath=''{.spec.strategy.type}''

# rollingUpdate 를 null 로 비우지 않으면 "may not be specified when strategy type is Recreate" 오류가 난다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.txt; mkdir -p /tmp/lab; kubectl delete deploy web web2 -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod sp -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod -l app=gen -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment web -n $NS --image=nginx:1.25 --replicas=2 >/dev/null; kubectl rollout status deployment/web -n $NS --timeout=120s >/dev/null 2>&1; sleep 1\\n"]', '["sh", "-c", "( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.strategy.type}'' 2>/dev/null)\\" = Recreate ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "전략이 Recreate 다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.strategy.type}'' 2>/dev/null)\\" = Recreate ]"]}]', '[{"title": "Deployment 전략", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/#strategy"}]'),
  (496, 2, '이미지와 환경 변수를 한 번에 배포하기 (rollout pause·resume)', '**배경** — 설정을 하나 바꿀 때마다 롤아웃이 일어나면 변경 두 개가 **롤아웃 두 번**이 됩니다. **`kubectl rollout pause`** 로 멈춰 두고 여러 변경을 한 뒤 **`kubectl rollout resume`** 하면 **한 번의 롤아웃(개정 하나)**으로 묶입니다. 멈춘 동안에는 `set image`·`set env` 를 해도 Pod 가 바뀌지 않습니다. Deployment `web`(`nginx:1.25`, 컨테이너 이름 `nginx`)이 있습니다.

**문제** — `web` 을 일시 중지하고 이미지를 **`nginx:1.26`** 으로, 환경 변수 **`MODE=blue`** 를 설정한 뒤 재개해 **롤아웃이 끝나게** 하세요. (개정은 처음 것과 새 것, **2개만** 있어야 합니다.)', '`kubectl rollout pause deploy/web` → `kubectl set image deploy/web nginx=nginx:1.26` → `kubectl set env deploy/web MODE=blue` → `kubectl rollout resume deploy/web` → `kubectl rollout status deploy/web`', 'kubectl rollout pause deploy/web -n $NS
kubectl set image deploy/web nginx=nginx:1.26 -n $NS
kubectl set env deploy/web MODE=blue -n $NS
kubectl rollout resume deploy/web -n $NS
kubectl rollout status deploy/web -n $NS --timeout=120s
kubectl rollout history deploy/web -n $NS

# 개정이 1, 2 두 개뿐이다. 중지하지 않았다면 3개가 된다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.txt; mkdir -p /tmp/lab; kubectl delete deploy web web2 -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod sp -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod -l app=gen -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment web -n $NS --image=nginx:1.25 --replicas=2 >/dev/null; kubectl rollout status deployment/web -n $NS --timeout=120s >/dev/null 2>&1; sleep 1\\n"]', '["sh", "-c", "( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.26 ] ) && ( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].env[?(@.name==\\"MODE\\")].value}'' 2>/dev/null)\\" = blue ] ) && ( [ \\"$(kubectl rollout history deploy/web -n $NS 2>/dev/null | grep -c ''^[0-9]'')\\" = 2 ] ) && ( [ -z \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.paused}'' 2>/dev/null)\\" ] ) && ( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.status.readyReplicas}'' 2>/dev/null)\\" = 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이미지가 nginx:1.26 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.26 ]"]}, {"label": "MODE 가 blue 다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].env[?(@.name==\\"MODE\\")].value}'' 2>/dev/null)\\" = blue ]"]}, {"label": "개정이 2개다", "cmd": ["sh", "-c", "[ \\"$(kubectl rollout history deploy/web -n $NS 2>/dev/null | grep -c ''^[0-9]'')\\" = 2 ]"]}, {"label": "중지 상태가 아니다", "cmd": ["sh", "-c", "[ -z \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.paused}'' 2>/dev/null)\\" ]"]}, {"label": "2개가 준비됐다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.status.readyReplicas}'' 2>/dev/null)\\" = 2 ]"]}]', '[{"title": "Deployment 일시 중지·재개", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/#pausing-and-resuming-a-deployment"}]'),
  (496, 3, '준비된 뒤 잠깐 더 지켜보기 (minReadySeconds)', '**배경** — Pod 가 Ready 가 돼도 **곧바로 "사용 가능(available)"으로 치지 않고** `minReadySeconds` 만큼 **문제없이 버틴 뒤**에야 사용 가능으로 셉니다. 롤링 업데이트는 사용 가능 수를 기준으로 다음 Pod 로 넘어가므로, 뜨자마자 죽는 새 버전이 옛 Pod 를 모두 밀어내는 일을 막습니다. Deployment `web` 이 있습니다.

**문제** — `web` 의 **`minReadySeconds`** 를 **`10`** 으로 설정하세요.', '`kubectl patch deploy web -p ''{"spec":{"minReadySeconds":10}}''`', 'kubectl patch deploy web -n $NS -p ''{"spec":{"minReadySeconds":10}}''
kubectl get deploy web -n $NS -o jsonpath=''{.spec.minReadySeconds}''

# 기본값은 0. readinessProbe 와 함께 쓰면 "준비"와 "안정"을 따로 확인한다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.txt; mkdir -p /tmp/lab; kubectl delete deploy web web2 -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod sp -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod -l app=gen -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment web -n $NS --image=nginx:1.25 --replicas=2 >/dev/null; kubectl rollout status deployment/web -n $NS --timeout=120s >/dev/null 2>&1; sleep 1\\n"]', '["sh", "-c", "( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.minReadySeconds}'' 2>/dev/null)\\" = 10 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "minReadySeconds 가 10 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.minReadySeconds}'' 2>/dev/null)\\" = 10 ]"]}]', '[{"title": "Deployment", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}]'),
  (496, 4, '옛 ReplicaSet 을 몇 개만 남기기 (revisionHistoryLimit)', '**배경** — 롤아웃마다 옛 ReplicaSet 이 **0개짜리로 남아** 롤백에 쓰입니다. 기본으로 10개까지 남기는데, **`revisionHistoryLimit`** 로 이 수를 줄이면 오래된 ReplicaSet 이 정리됩니다. 너무 줄이면 롤백할 지점이 없어집니다. Deployment `web`(`nginx:1.25`)이 있습니다.

**문제** — `web` 의 `revisionHistoryLimit` 를 **`1`** 로 설정한 뒤, 이미지를 **`nginx:1.26`** → **`nginx:1.27-alpine`** → **`nginx:1.26-alpine`** 순으로 **세 번** 바꾸세요. (각각 롤아웃이 끝난 뒤 다음으로 가세요. 끝나면 ReplicaSet 은 **현재 것 + 옛것 1개 = 2개**만 남아야 합니다.)', '`kubectl patch` 로 limit 를 1 로 → `kubectl set image deploy/web nginx=...` 와 `kubectl rollout status deploy/web` 를 세 번 반복', 'kubectl patch deploy web -n $NS -p ''{"spec":{"revisionHistoryLimit":1}}''
for i in nginx:1.26 nginx:1.27-alpine nginx:1.26-alpine; do
  kubectl set image deploy/web nginx=$i -n $NS
  kubectl rollout status deploy/web -n $NS --timeout=120s
done
kubectl get rs -l app=web -n $NS

# limit 가 기본(10)이면 ReplicaSet 이 4개 남는다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.txt; mkdir -p /tmp/lab; kubectl delete deploy web web2 -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod sp -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod -l app=gen -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment web -n $NS --image=nginx:1.25 --replicas=2 >/dev/null; kubectl rollout status deployment/web -n $NS --timeout=120s >/dev/null 2>&1; sleep 1\\n"]', '["sh", "-c", "( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.revisionHistoryLimit}'' 2>/dev/null)\\" = 1 ] ) && ( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.26-alpine ] ) && ( [ \\"$(kubectl get rs -l app=web -n $NS --no-headers 2>/dev/null | wc -l | tr -d '' '')\\" = 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "revisionHistoryLimit 가 1 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.revisionHistoryLimit}'' 2>/dev/null)\\" = 1 ]"]}, {"label": "이미지가 nginx:1.26-alpine 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.26-alpine ]"]}, {"label": "ReplicaSet 이 2개다", "cmd": ["sh", "-c", "[ \\"$(kubectl get rs -l app=web -n $NS --no-headers 2>/dev/null | wc -l | tr -d '' '')\\" = 2 ]"]}]', '[{"title": "개정 이력 한도", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/#clean-up-policy"}]'),
  (496, 5, '명령까지 지정해 Deployment 만들기 (create deployment -- 명령)', '**배경** — `kubectl create deployment` 는 이름·이미지·`--replicas` 를 받고, **`--` 뒤에 적은 것을 컨테이너 명령**으로 씁니다. YAML 을 쓰지 않고도 `sleep` 처럼 계속 도는 명령을 가진 Deployment 를 만들 수 있습니다.

**문제** — 이미지 `busybox:1.36`, **replicas 2** 로 Deployment **`web2`** 를 만들고 명령을 **`sleep 3600`** 으로 지정하세요. (2개가 준비될 때까지 기다리세요.)', '`kubectl create deployment web2 --image=busybox:1.36 --replicas=2 -- sleep 3600`', 'kubectl create deployment web2 -n $NS --image=busybox:1.36 --replicas=2 -- sleep 3600
kubectl rollout status deploy/web2 -n $NS --timeout=120s
kubectl get deploy web2 -n $NS -o jsonpath=''{.spec.template.spec.containers[0].command}''

# -- 앞은 kubectl 옵션, 뒤는 컨테이너 명령이다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.txt; mkdir -p /tmp/lab; kubectl delete deploy web web2 -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod sp -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod -l app=gen -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; true\\n"]', '["sh", "-c", "( [ \\"$(kubectl get deploy web2 -n $NS -o jsonpath=''{.spec.template.spec.containers[0].command}'' 2>/dev/null)\\" = ''[\\"sleep\\",\\"3600\\"]'' ] ) && ( [ \\"$(kubectl get deploy web2 -n $NS -o jsonpath=''{.spec.replicas}'' 2>/dev/null)\\" = 2 ] ) && ( [ \\"$(kubectl get deploy web2 -n $NS -o jsonpath=''{.status.readyReplicas}'' 2>/dev/null)\\" = 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "명령이 sleep 3600 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web2 -n $NS -o jsonpath=''{.spec.template.spec.containers[0].command}'' 2>/dev/null)\\" = ''[\\"sleep\\",\\"3600\\"]'' ]"]}, {"label": "replicas 가 2 다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web2 -n $NS -o jsonpath=''{.spec.replicas}'' 2>/dev/null)\\" = 2 ]"]}, {"label": "2개가 준비됐다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web2 -n $NS -o jsonpath=''{.status.readyReplicas}'' 2>/dev/null)\\" = 2 ]"]}]', '[{"title": "Deployment", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}]'),
  (496, 6, '같은 파일로 이름이 다른 Pod 만들기 (generateName)', '**배경** — `metadata.name` 대신 **`generateName`** 에 접두사를 적으면 서버가 **뒤에 무작위 문자를 붙여** 이름을 정합니다. 같은 파일로 여러 개를 만들 수 있지만 이름이 매번 달라서 **`kubectl apply` 는 쓸 수 없고 `kubectl create`** 를 써야 합니다. `/tmp/lab/gen.yaml` 에 `generateName: run-` 인 Pod(라벨 `app=gen`)가 있습니다.

**문제** — 이 파일로 Pod 를 **2개** 만들고 모두 **Running** 이 되게 하세요.', '`kubectl create -f /tmp/lab/gen.yaml` 을 두 번 실행해요.', 'kubectl create -n $NS -f /tmp/lab/gen.yaml
kubectl create -n $NS -f /tmp/lab/gen.yaml
kubectl wait --for=condition=Ready pod -l app=gen -n $NS --timeout=90s
kubectl get pod -l app=gen -n $NS

# run-x7k2p, run-9fhzq 처럼 이름이 달라진다. apply 는 이름이 없어 실패한다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.txt; mkdir -p /tmp/lab; kubectl delete deploy web web2 -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod sp -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod -l app=gen -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; cat > /tmp/lab/gen.yaml <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  generateName: run-\\n  labels: {app: gen}\\nspec:\\n  terminationGracePeriodSeconds: 0\\n  containers:\\n  - {name: c, image: \\"busybox:1.36\\", command: [\\"sleep\\", \\"3600\\"]}\\nEOF\\n"]', '["sh", "-c", "( [ \\"$(kubectl get pod -l app=gen -n $NS --no-headers 2>/dev/null | wc -l | tr -d '' '')\\" = 2 ] ) && ( [ \\"$(kubectl get pod -l app=gen -n $NS --no-headers 2>/dev/null | grep -c Running)\\" = 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "app=gen Pod 가 2개다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod -l app=gen -n $NS --no-headers 2>/dev/null | wc -l | tr -d '' '')\\" = 2 ]"]}, {"label": "모두 Running 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod -l app=gen -n $NS --no-headers 2>/dev/null | grep -c Running)\\" = 2 ]"]}]', '[{"title": "객체 이름 (generateName)", "url": "https://kubernetes.io/docs/concepts/overview/working-with-objects/names/"}]'),
  (496, 7, '사이드카에서 다른 컨테이너 프로세스 보기 (shareProcessNamespace)', '**배경** — 컨테이너는 기본적으로 **자기 프로세스만** 봅니다. Pod 에 **`shareProcessNamespace: true`** 를 주면 같은 Pod 의 컨테이너들이 **서로의 프로세스**를 보게 되어, 쉘이 없는 이미지를 디버깅 사이드카에서 `ps` 로 살펴볼 수 있습니다.

**문제** — Pod **`sp`** 를 만드세요. 컨테이너는 `web`(`nginx:1.25`)과 `dbg`(`busybox:1.36`, `sleep 3600`) 두 개이고 **프로세스 네임스페이스를 공유**해야 합니다. (`dbg` 에서 `ps` 를 하면 nginx 가 보여야 합니다.)', 'Pod 스펙 최상위에 `shareProcessNamespace: true` 를 적어요.', 'kubectl apply -n $NS -f - <<''EOF''
apiVersion: v1
kind: Pod
metadata: {name: sp}
spec:
  terminationGracePeriodSeconds: 0
  shareProcessNamespace: true
  containers:
  - {name: web, image: "nginx:1.25"}
  - {name: dbg, image: "busybox:1.36", command: ["sleep", "3600"]}
EOF
kubectl wait --for=condition=Ready pod/sp -n $NS --timeout=90s
kubectl exec sp -n $NS -c dbg -- ps

# 공유하면 PID 1 이 pause 프로세스가 되고 nginx 도 목록에 보인다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.txt; mkdir -p /tmp/lab; kubectl delete deploy web web2 -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod sp -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod -l app=gen -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; true\\n"]', '["sh", "-c", "( [ \\"$(kubectl get pod sp -n $NS -o jsonpath=''{.spec.shareProcessNamespace}'' 2>/dev/null)\\" = true ] ) && ( kubectl exec sp -n $NS -c dbg -- ps 2>/dev/null | grep -q nginx )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "shareProcessNamespace 가 true 다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod sp -n $NS -o jsonpath=''{.spec.shareProcessNamespace}'' 2>/dev/null)\\" = true ]"]}, {"label": "dbg 에서 nginx 가 보인다", "cmd": ["sh", "-c", "kubectl exec sp -n $NS -c dbg -- ps 2>/dev/null | grep -q nginx"]}]', '[{"title": "Pod 의 프로세스 네임스페이스 공유", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/share-process-namespace/"}]'),
  (496, 8, '배포 사유를 이력에 남기기 (change-cause)', '**배경** — `kubectl rollout history` 의 **CHANGE-CAUSE** 칸은 Deployment 의 **`kubernetes.io/change-cause` 어노테이션** 값입니다. 비워 두면 `<none>` 이라 어떤 배포인지 알기 어렵습니다. 이미지를 바꾼 뒤 이 어노테이션을 달아 두면 이력에 사유가 남습니다. Deployment `web`(`nginx:1.25`, 컨테이너 `nginx`)이 있습니다.

**문제** — `web` 의 이미지를 **`nginx:1.26`** 으로 바꾸고 롤아웃이 끝난 뒤, 사유 **`upgrade to 1.26`** 을 `change-cause` 어노테이션으로 달아 **`rollout history`** 에 보이게 하세요.', '`kubectl set image deploy/web nginx=nginx:1.26` → `kubectl rollout status` → `kubectl annotate deploy/web kubernetes.io/change-cause="upgrade to 1.26"`', 'kubectl set image deploy/web nginx=nginx:1.26 -n $NS
kubectl rollout status deploy/web -n $NS --timeout=120s
kubectl annotate deploy/web -n $NS kubernetes.io/change-cause=''upgrade to 1.26''
kubectl rollout history deploy/web -n $NS

# 사유가 CHANGE-CAUSE 칸에 나타난다. 배포 때마다 사유를 갱신한다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.txt; mkdir -p /tmp/lab; kubectl delete deploy web web2 -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod sp -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod -l app=gen -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment web -n $NS --image=nginx:1.25 --replicas=2 >/dev/null; kubectl rollout status deployment/web -n $NS --timeout=120s >/dev/null 2>&1; sleep 1\\n"]', '["sh", "-c", "( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.26 ] ) && ( kubectl rollout history deploy/web -n $NS 2>/dev/null | grep -q \\"upgrade to 1.26\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이미지가 nginx:1.26 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.26 ]"]}, {"label": "이력에 사유가 보인다", "cmd": ["sh", "-c", "kubectl rollout history deploy/web -n $NS 2>/dev/null | grep -q \\"upgrade to 1.26\\""]}]', '[{"title": "개정 이력 한도", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/#clean-up-policy"}]'),
  (496, 9, '지금 Pod 를 거느린 ReplicaSet 찾기', '**배경** — Deployment 는 롤아웃마다 새 ReplicaSet 을 만들고 옛것은 **0개짜리로 남겨** 둡니다. 지금 Pod 를 실제로 거느린 ReplicaSet 은 `replicas` 가 0보다 큰 것이고, Pod 이름 가운데 해시(`pod-template-hash`)가 그 ReplicaSet 이름의 끝과 같습니다. Deployment `web` 은 이미지를 한 번 바꿔 ReplicaSet 이 2개입니다.

**문제** — **현재 Pod 를 거느린 ReplicaSet 의 이름**을 **`/tmp/q9.txt`** 에 저장하세요.', '`kubectl get rs -l app=web` 에서 DESIRED 가 0 이 아닌 것을 찾거나 jsonpath 필터 `[?(@.status.replicas>0)]` 를 써요.', 'kubectl get rs -l app=web -n $NS -o jsonpath=''{.items[?(@.status.replicas>0)].metadata.name}'' > /tmp/q9.txt
cat /tmp/q9.txt

# 옛 ReplicaSet 은 DESIRED 0 으로 남아 롤백에 쓰인다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.txt; mkdir -p /tmp/lab; kubectl delete deploy web web2 -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod sp -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod -l app=gen -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment web -n $NS --image=nginx:1.25 --replicas=2 >/dev/null; kubectl rollout status deployment/web -n $NS --timeout=120s >/dev/null 2>&1; sleep 1\\nkubectl set image deploy/web nginx=nginx:1.26 -n $NS; kubectl rollout status deploy/web -n $NS --timeout=120s >/dev/null 2>&1; sleep 2\\n"]', '["sh", "-c", "( [ \\"$(cat /tmp/q9.txt 2>/dev/null)\\" = \\"$(kubectl get rs -l app=web -n $NS -o jsonpath=''{.items[?(@.status.replicas>0)].metadata.name}'')\\" ] && [ -n \\"$(cat /tmp/q9.txt)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "현재 ReplicaSet 이름이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q9.txt 2>/dev/null)\\" = \\"$(kubectl get rs -l app=web -n $NS -o jsonpath=''{.items[?(@.status.replicas>0)].metadata.name}'')\\" ] && [ -n \\"$(cat /tmp/q9.txt)\\" ]"]}]', '[{"title": "ReplicaSet", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/replicaset/"}]'),
  (496, 10, 'Recreate 전략이 알맞은 경우', '`strategy.type: Recreate` 가 `RollingUpdate` 보다 **알맞은** 경우는 언제일까요?', '두 버전이 동시에 떠 있으면 안 되는 앱을 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["배포 중에도 서비스가 끊기면 안 될 때", "두 버전이 동시에 실행되면 데이터가 꼬이는 앱을 바꿀 때", "배포를 가능한 한 빨리 끝내고 싶을 때", "새 버전을 일부 사용자에게만 먼저 보여 줄 때"]', 1, 'Recreate 는 옛 Pod 를 모두 내린 뒤 새 Pod 를 올려 두 버전이 겹치지 않지만 그 사이 서비스가 중단됩니다. 무중단이 필요하면 RollingUpdate, 일부에게만 먼저 보이려면 카나리 배포를 씁니다.', NULL, NULL, NULL, '[{"title": "Deployment 전략", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/#strategy"}]'),
  (496, 11, '변경을 모아 한 번에 배포', '여러 변경을 한 번의 롤아웃으로 묶으려고 Deployment 를 멈추는 명령입니다. 빈칸을 채우세요.', '"일시 중지" 의 영어예요.', NULL, NULL, '[]', 'fill', '["pause", "stop", "hold", "freeze"]', NULL, '`kubectl rollout pause` 로 멈춘 동안의 변경은 Pod 에 반영되지 않고 쌓이다가, `kubectl rollout resume` 하면 한 번의 롤아웃으로 적용됩니다. stop·hold·freeze 는 rollout 하위 명령이 아닙니다.', '[0]', 'kubectl rollout {0} deployment/web', NULL, '[{"title": "Deployment 일시 중지·재개", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/#pausing-and-resuming-a-deployment"}]'),
  (496, 12, '여러 변경을 한 번의 롤아웃으로 배포하는 순서', '이미지와 환경 변수를 함께 바꿔 한 번에 배포하는 순서입니다. 순서에 맞게 놓아 보세요.', '멈춤 → 변경들 → 재개 → 확인이에요.', NULL, NULL, '[]', 'order', '["`kubectl rollout pause deploy/web` 로 롤아웃을 멈춘다", "`kubectl set image` 로 이미지를 바꾼다", "`kubectl set env` 로 환경 변수를 바꾼다", "`kubectl rollout resume deploy/web` 로 재개하고 `rollout status` 로 완료를 확인한다"]', NULL, '멈춘 동안의 변경은 Pod 템플릿에만 기록됩니다. 재개하는 순간 모인 변경이 한 번의 롤아웃(개정 하나)으로 적용되고 rollout status 로 완료를 확인합니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "Deployment 일시 중지·재개", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/#pausing-and-resuming-a-deployment"}]');
